// usage: node mk.mjs <outfile> <casesModule>
// cases module default-exports an array of [instance, schema] JS values.
import { writeFileSync } from 'node:fs';
const [,, out, mod] = process.argv;
const cases = (await import(mod)).default;
writeFileSync(out, JSON.stringify(cases.map(([i, s]) => ({
  a: typeof i === 'string' ? i : JSON.stringify(i),
  b: typeof s === 'string' ? s : JSON.stringify(s),
})), null, 0));
console.log('wrote', out, cases.length, 'cases');
EOF
echo ok

