// nested defs
P(J(1), J({$ref:"#/$defs/a/$defs/b", $defs:{a:{$defs:{b:{type:"string"}}}}}));
// $ref to properties subschema
P(J(1), J({$ref:"#/properties/a", properties:{a:{type:"string"}}}));
// $ref to "#" root self-recursive
P(J({a:{a:1}}), J({type:"object", properties:{a:{$ref:"#"}}}));
P(J({a:{a:"x"}}), J({type:"object", properties:{a:{$ref:"#"}}}));
// $ref "#" with no progress -> recursion?
P(J(1), J({$ref:"#"}));
// non-existent pointer
P(J(1), J({$ref:"#/$defs/nope", $defs:{x:{}}}));
P(J(1), J({$ref:"#/nope/deep"}));
P(J(1), J({$ref:"#/$defs/x/nope", $defs:{x:{}}}));
// array pointer in-range and out-of-range
P(J(1), J({$ref:"#/prefixItems/0", prefixItems:[{type:"string"}]}));
P(J(1), J({$ref:"#/prefixItems/5", prefixItems:[{type:"string"}]}));
P(J(1), J({$ref:"#/prefixItems/-1", prefixItems:[{type:"string"}]}));
P(J(1), J({$ref:"#/prefixItems/01", prefixItems:[{type:"string"}]}));
P(J(1), J({$ref:"#/prefixItems/a", prefixItems:[{type:"string"}]}));
// escapes
P(J(1), J({$ref:"#/$defs/a~0b", $defs:{"a~b":{type:"string"}}}));
P(J(1), J({$ref:"#/$defs/a~1b", $defs:{"a/b":{type:"string"}}}));
P(J(1), J({$ref:"#/$defs/a%20b", $defs:{"a b":{type:"string"}}}));
P(J(1), J({$ref:"#/$defs/a b", $defs:{"a b":{type:"string"}}}));
P(J(1), J({$ref:"#/$defs/a%25b", $defs:{"a%b":{type:"string"}}}));
P(J(1), J({$ref:"#/$defs/a%b", $defs:{"a%b":{type:"string"}}}));
P(J(1), J({$ref:"#/$defs/é", $defs:{"é":{type:"string"}}}));
P(J(1), J({$ref:"#/$defs/%C3%A9", $defs:{"é":{type:"string"}}}));
P(J(1), J({$ref:"#/$defs/a%2Fb", $defs:{"a/b":{type:"string"}}}));
P(J(1), J({$ref:"#/$defs/", $defs:{"":{type:"string"}}}));
P(J(1), J({$ref:"", $defs:{"":{type:"string"}}}));
P(J(1), J({$ref:"#", type:"string"}));
// sibling keyword alongside $ref
P(J(1), J({$ref:"#/$defs/x", type:"string", $defs:{x:{minimum:5}}}));
P(J("ab"), J({$ref:"#/$defs/x", type:"string", $defs:{x:{minLength:5}}}));
P(J(1), J({$ref:"#/$defs/x", $defs:{x:{type:"string"}}, minimum:5}));
export default c;
EOF
